import * as React from 'react';
import styles from './OurValues.module.scss';
import type { IOurValuesProps } from './IOurValuesProps';
import { SPHttpClient } from '@microsoft/sp-http';

type CardItem = { icon?: string; title: string; desc: string };
type State = { items: CardItem[]; loading: boolean; error?: string };

export default class OurValues extends React.Component<IOurValuesProps, State> {
  state: State = { items: [], loading: true };

  componentDidMount() { this.loadItems(); }

  /** Fetch items from the list and map to cards */
  private async loadItems() {
    const webUrl   = this.props.context.pageContext.web.absoluteUrl;
    const listName = 'AboutDHREOurValues';   // <-- your list title

    // No $expand (OVIcon is Hyperlink/Picture on your list)
    const url =
      `${webUrl}/_api/web/lists/getbytitle('${encodeURIComponent(listName)}')/items` +
      `?$select=Id,Title,OVDescription,OVIcon,OVSortOrder` +
      `&$orderby=OVSortOrder asc, Id asc`; 

    try {
      const res = await this.props.context.spHttpClient.get(url, SPHttpClient.configurations.v1);

      if (!res.ok) {
        const text = await res.text();
        throw new Error(`REST ${res.status}: ${text}`);
      }

      const json = await res.json();

      const items: CardItem[] = (json.value || []).map((it: any) => {
        const raw = it?.OVIcon;
        let icon = '';
        if (raw) {
          if (typeof raw === 'string') icon = raw;        // Hyperlink/Picture column
          else if (raw.Url)            icon = raw.Url;    // Image column (modern)
        }
        return { icon, title: it?.Title || '', desc: it?.OVDescription || '' };
      });

      this.setState({ items, loading: false, error: undefined });
    } catch (e: any) {
      this.setState({ loading: false, error: e?.message || 'Failed to load items.' });
    }
  }

  render() {
    const { items, loading, error } = this.state;

    return (
      <section className={`${styles.ourValues} ${styles.fullBleed}`}>
        <div className={styles.container}>
          <div className={styles.heading}>
            <span className={styles.headingOur}>Our</span>
            <span className={styles.headingValues}>Values</span>
          </div>

          {loading && <div>Loading…</div>}
          {error && !loading && <div style={{ color: '#c00' }}>{error}</div>}

          {!loading && !error && (
            <div className={styles.grid}>
              {items.map((c, i) => (
                <article key={i} className={styles.card}>
                  <div className={styles.iconWrap}>
                    {c.icon ? <img src={c.icon} alt="" className={styles.icon} /> : null}
                  </div>
                  <h3 className={styles.cardTitle}>{c.title}</h3>
                  <p className={styles.cardDesc}>{c.desc}</p>
                </article>
              ))}
            </div>
          )}
        </div>
      </section>
    );
  }
}
